"""Produce concise manager handoff after both official matrices validate."""
import json
from pathlib import Path
A=Path(__file__).resolve().parent
read=lambda p:json.loads(Path(p).read_text(encoding='utf-8-sig'))
def main():
 aa=read(A/'runs/C024-TIMING-01/VALIDATED_SUMMARY_V1.json');bb=read(A/'runs/C024-B-TIMING-01/VALIDATED_SUMMARY_V1.json');ca=read(A/'runs/C024-CORRECTNESS-01/correctness_report.json');cb=read(A/'runs/C024-B-CORRECTNESS-01/correctness_report.json');supp=read(A/'runs/C024-SUPPLEMENT-02/REPORT_V2.json')
 integrated=read(A/'runs/C024-INTEGRATED-CORRECTNESS-01/correctness_report.json');smoke=read(A/'runs/C024-INTEGRATED-CLI-01/REPORT_V1.json')
 summary={'integrated':{'correctness_calls':680,'errors':integrated['errors'],'CLI_smoke_errors':smoke['errors'],'CLI_cases':[{'case':r['case'],'status':r.get('status'),'search_nodes':r.get('metrics',{}).get('search_nodes')} for r in smoke['rows']],'official_timing_measured':False},'memory_measured':False,'state':'A_B_and_integrated_audited_no_public_promotion_performed','A':{k:aa[k] for k in ['semantic_certificate_pass','material_benefit','unique_stress_candidate_reduction','known_k_guardrails_pass','automatic_promotion_criteria_pass','comparisons','summaries']},'B':{k:bb[k] for k in ['semantic_certificate_pass','material_benefit','known_k_guardrails_pass','automatic_promotion_criteria_pass','comparisons','summaries']},'correctness':{'A_errors':ca['errors'],'A_calls_per_provider':689,'A_distinct_job_ids':668,'A_unique_inputs':196,'supplement_errors':supp['errors'],'supplement_calls_per_provider':10,'B_errors':cb['errors'],'B_calls_per_provider':680,'B_unique_inputs':202,'capture_integrity':read(A/'CORRECTNESS_CAPTURE_INTEGRITY_V2.json')},'disclosures':['21 repeated A job IDs retained; V2 addendum corrects earlier count','Manager harness-review arrived after A launch; no discarded/restarted timing','Raw distributions.json includes unresolved durations; validated summary exclusively controls acceptance','Supplement preparation KeyError preserved as C024-SUPP-PREP-001; fixed in new script before any supplemental provider execution','Integrated: 680 independently replayed calls and four CLI checks pass; integrated timing unmeasured','No memory measurement performed; no historical cross-round ratios; no implementation or public changes'],'official_attempts':120,'commands':{'A_replay':'py -B -X utf8 results/2026-11-05/search_checkpoint_v24/audit/validate_timing_v1.py results/2026-11-05/search_checkpoint_v24/audit/runs/C024-TIMING-01','B_replay':'py -B -X utf8 results/2026-11-05/search_checkpoint_v24/audit/validate_timing_b_v2.py results/2026-11-05/search_checkpoint_v24/audit/runs/C024-B-TIMING-01'}}
 (A/'FINAL_SUMMARY_V2.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');(A/'READINESS_V2.json').write_text(json.dumps({'state':summary['state'],'official_timing_run':True,'A_acceptance':aa['automatic_promotion_criteria_pass'],'B_acceptance':bb['automatic_promotion_criteria_pass'],'errors':{'A':len(aa['errors']),'B':len(bb['errors']),'integrated':integrated['errors']+smoke['errors'],'correctness':ca['errors']+cb['errors']+supp['errors']},'manager_summary':str(A/'FINAL_SUMMARY_V2.json')},indent=2)+'\n',encoding='utf-8')
 lines=['# C024 audit results V1','',f"A automatic-promotion criteria: {aa['automatic_promotion_criteria_pass']}. B: {bb['automatic_promotion_criteria_pass']}. Final promotion remains the manager decision.",'','| Round | Cell | Baseline median s | Candidate median s | Candidate/baseline | Baseline completed | Candidate completed |','|---|---|---:|---:|---:|---:|---:|']
 for name,report,provider in [('A',aa,'C024_A'),('B',bb,'C024_B')]:
  for c in report['comparisons']:
   b=next(x for x in report['summaries'] if x['cell_id']==c['cell_id'] and x['provider']=='C020_C2');a=next(x for x in report['summaries'] if x['cell_id']==c['cell_id'] and x['provider']==provider)
   fmt=lambda v:'censored' if v is None else f'{v:.4f}'
   lines.append(f"| {name} | {c['cell_id']} | {fmt(b['median_completed_seconds'])} | {fmt(a['median_completed_seconds'])} | {fmt(c['candidate_over_baseline_median'])} | {b['completed']}/5 | {a['completed']}/5 |")
 lines+=['','Zero completed semantic/certificate errors is required. Full distributions, counters, replay outcomes and capture identifiers are in each VALIDATED_SUMMARY_V1.json; all stdout/stderr and immutable source snapshots remain in attempts/ and source_blobs/.','',*['- '+x for x in summary['disclosures']]]
 (A/'RESULTS_V1.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print({'A_acceptance':aa['automatic_promotion_criteria_pass'],'B_acceptance':bb['automatic_promotion_criteria_pass']})
if __name__=='__main__':main()
